#!/usr/bin/env bash
# Back up everything that would be painful to lose: the database, and the CV.
#
# The CV is dumped separately even though it lives in Postgres. A pg_dump is
# restorable only by a working Postgres of a compatible version; the JSON is
# readable by a human on any machine, and it is the one artefact that cannot be
# regenerated by re-crawling. Two formats, two failure modes.
#
# Install:  cp deploy/jobpilot-backup.{service,timer} /etc/systemd/system/
#           systemctl enable --now jobpilot-backup.timer

set -euo pipefail

APP_DIR="${APP_DIR:-/opt/jobpilot}"
BACKUP_DIR="${BACKUP_DIR:-/var/backups/jobpilot}"
KEEP_DAYS="${KEEP_DAYS:-30}"

cd "$APP_DIR"
# DATABASE_URL and friends. `set -a` exports them for pg_dump without echoing
# them anywhere.
set -a
# shellcheck disable=SC1091
source .env
set +a

mkdir -p "$BACKUP_DIR"
stamp="$(date +%Y%m%d-%H%M%S)"

# pg_dump speaks libpq URLs, not SQLAlchemy ones — strip the +psycopg driver
# suffix or it fails with "invalid URI scheme".
pg_url="${DATABASE_URL/postgresql+psycopg:/postgresql:}"

# Custom format (-Fc): compressed, and restorable table-by-table with pg_restore
# instead of all-or-nothing.
pg_dump -Fc "$pg_url" -f "$BACKUP_DIR/jobpilot-$stamp.dump"

# The Master CV as plain JSON. Never committed — it is personal data (CLAUDE.md
# principle 3) and this directory is outside the repo for that reason.
.venv/bin/python -m jobpilot.cli cv export "$BACKUP_DIR/cv-$stamp.json"

# Verify rather than assume. A backup job that reports success while writing a
# zero-byte file is worse than no backup job, because it stops you looking.
for f in "$BACKUP_DIR/jobpilot-$stamp.dump" "$BACKUP_DIR/cv-$stamp.json"; do
    if [ ! -s "$f" ]; then
        echo "backup produced an empty file: $f" >&2
        exit 1
    fi
done

find "$BACKUP_DIR" -name 'jobpilot-*.dump' -mtime "+$KEEP_DAYS" -delete
find "$BACKUP_DIR" -name 'cv-*.json' -mtime "+$KEEP_DAYS" -delete

echo "backed up to $BACKUP_DIR (jobpilot-$stamp.dump, cv-$stamp.json)"
